25: func parkProjectIfIdle(ctx context.Context, db *store.DB, project store.Project, now time.Time) (bool, error) {
26: 	tasks, err := db.LiveTasks(ctx, project.ID)
27: 	if err != nil {
28: 		return false, err
29: 	}
30: 	if !projectReadyToPark(project, tasks, now, projectParkGrace) {
31: 		return false, nil
32: 	}
33: 	return db.ParkProjectIfIdle(ctx, project, now, projectParkGrace)
34: }
