func (s *Service) restartLead(ctx context.Context, db *store.DB, home string, project store.Project, cfg config.Config, snapshot herdr.Snapshot) (returnErr error) {
	if err := refuseForeignLeadForProject(snapshot, project, os.Getenv("HERDR_PANE_ID")); err != nil {
		return err
	}
	now := time.Now()
	claimed, err := db.ClaimLeadStart(ctx, project.ID, now.UnixMilli(), now.Add(-2*time.Minute).UnixMilli(), "restore", os.Getpid())
	if err != nil {
		return err
	}
	if !claimed {
		return nil
	}
	defer func() {
		releaseCtx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
		defer cancel()
		if releaseErr := db.ReleaseLeadStart(releaseCtx, project.ID, "restore", os.Getpid()); releaseErr != nil {
			returnErr = errors.Join(returnErr, fmt.Errorf("release Lead start claim: %w", releaseErr))
		}
	}()
	var current *herdr.Pane
	leadLabel := project.LeadLabel
	if leadLabel == "" {
		leadLabel = "posse:" + project.Name + ":lead"
	}
	for i := range snapshot.Panes {
		pane := &snapshot.Panes[i]
		if pane.PaneID == project.LeadPaneID && project.LeadPaneID != "" || pane.Label == leadLabel {
			current = pane
			break
		}
	}
	if current != nil && current.Agent != "" {
		if err := s.stopLeadAgent(ctx, current.PaneID, current.Agent); err != nil {
			return err
		}
	}
	if current == nil {
		var created json.RawMessage
		var err error
		created, err = s.herdrCall(ctx, "tab.create", map[string]any{"workspace_id": project.HerdrWorkspaceID, "cwd": project.Root, "label": project.LeadLabel, "focus": false, "no_focus": true})
		if err != nil {
			return err
		}
		var result struct {
			RootPane struct {
				PaneID string `json:"pane_id"`
			} `json:"root_pane"`
		}
		if err := json.Unmarshal(created, &result); err != nil {
			return err
		}
		if result.RootPane.PaneID == "" {
			return axi.Failure("herdr_invalid_response", "Herdr did not return a pane for the restarted Lead", true)
		}
		current = &herdr.Pane{PaneID: result.RootPane.PaneID, WorkspaceID: project.HerdrWorkspaceID}
	}
	label := project.LeadLabel
	if label == "" {
		label = "posse:" + project.Name + ":lead"
	}
	if _, err := s.herdrCall(ctx, "pane.rename", map[string]any{"pane_id": current.PaneID, "label": label}); err != nil {
		return err
	}
	if _, err := s.herdrCall(ctx, "workspace.rename", map[string]any{"workspace_id": current.WorkspaceID, "label": leadWorkspaceLabel(project)}); err != nil {
		return err
	}
	kind, session, err := s.restoreLeadAgent(ctx, db, project, cfg)
	if err != nil {
		return err
	}
	if _, ok := cfg.Kinds[kind]; !ok {
		return axi.Failure("config_invalid", "unknown Lead agent kind "+kind, false)
	}
	if _, err := s.herdrCall(ctx, "pane.report_metadata", leadDisplayMetadata(project, current.PaneID, "", kind)); err != nil {
		return err
	}
	gaps, err := s.readiness(ctx, db, project, cfg)
	if err != nil {
		return err
	}
	leadStart, err := s.prepareLeadLaunch(home, project, cfg, kind, gaps)
	if err != nil {
		return err
	}
	leadStart = leadStart.withResume(cfg.Kinds[kind], session)
	launch, err := db.NextLeadLaunch(ctx, project.ID)
	if err != nil {
		return err
	}
	// Herdr's agent.start has no env parameter, so launchAgent exports the
	// environment only into the Lead's shell, not global config or other panes.
	if err := s.launchAgent(ctx, current.PaneID, leadAgentName(project.Name, launch), kind, leadStart.Args, leadStart.Env, filepath.Join(home, "projects", project.Name, "lead-launch.sh")); err != nil {
		return err
	}
	if err := s.waitLeadStarted(ctx, current.PaneID, leadStart); err != nil {
		return err
	}
	if err := db.SetProjectLeadAgent(ctx, project.ID, store.LeadAgent{Kind: kind, Session: session}); err != nil {
		return err
	}
	if err := db.SetProjectLead(ctx, project.ID, current.WorkspaceID, current.PaneID, label); err != nil {
		return err
	}
	project, err = db.ProjectByID(ctx, project.ID)
	if err != nil {
		return err
	}
	s.relabelProjectTabs(ctx, db, project)
	freshSnapshot, watchErr := s.snapshot(ctx)
	if watchErr == nil {
		watchErr = s.cleanupLegacyWatchTabs(ctx, db, project, freshSnapshot)
	}
	if watchErr == nil {
		watchErr = s.ensureWatchRuntime(ctx, db, home, project)
	}
	if watchErr != nil {
		_, _ = db.CreateNotice(ctx, store.Notice{ProjectID: project.ID, Kind: "pr_watch_failing", Summary: "Watch restart failed: " + truncate(watchErr.Error(), 240), DataJSON: `{}`})
	}
	if leadStart.TypedPrompt != "" {
		if err := s.deliverLaunchPrompt(ctx, current.PaneID, leadStart.TypedPrompt); err != nil {
			return err
		}
	}
	if leadStart.HandoffLoaded {
		if err := s.archiveStartedLeadHandoff(ctx, home, project); err != nil {
			return err
		}
	}
	return nil

